<script setup>
import { computed, onBeforeUnmount, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import AgentConversation from "@/components/agent/AgentConversation.vue";
import AgentIcon from "@/components/agent/AgentIcon.vue";
import AgentRadarChart from "@/components/agent/AgentRadarChart.vue";
import { useAgentStore } from "@/stores/agent";
import {
  agentProfile,
  careerDirections,
  careerPath,
  marketSignals,
  opportunities,
  roadmap,
  runStages,
  skills,
  weeklyActions,
} from "@/data/agentMockData";

defineOptions({ name: "AgentWorkspace" });
const store = useAgentStore();
const route = useRoute();
const router = useRouter();
const fileInput = ref(null);
const mobilePanel = ref("overview");
const selectedDirection = computed(() => careerDirections.find((item) => item.id === store.selectedDirection) || careerDirections[0]);
const highestGap = computed(() => skills.reduce((lowest, skill) => (skill.score < lowest.score ? skill : lowest), skills[0]));

function chooseDirection(id) { store.chooseDirection(id); }
function openFilePicker() { fileInput.value?.click(); }
function handleFile(event) { store.mockUpload(event.target.files?.[0]); event.target.value = ""; }
function isDone(id) { return store.completedActions.includes(id); }
function toggleSaved(id) { store.toggleSavedOpportunity(id); }
async function runAnalysis() {
  try {
    const result = await store.runAnalysis();
    if (result?.conversationId && result.conversationId !== "mock" && route.params.conversationId !== result.conversationId) {
      await router.replace({ name: "agent-conversation", params: { conversationId: result.conversationId } });
    }
  } catch {
    // Store exposes the user-facing error state.
  }
}

watch(
  () => route.params.conversationId,
  async (conversationId) => {
    if (!store.isApiMode) return;
    try {
      await store.loadCapabilities();
      await Promise.all([store.loadConversations(), store.loadProfile()]);
      if (conversationId) await store.openConversation(String(conversationId));
      else if (store.conversations.length) {
        await router.replace({
          name: "agent-conversation",
          params: { conversationId: String(store.conversations[0].id) },
        });
      }
    } catch (error) {
      if (error?.response?.status === 404) router.replace({ name: "agent" });
    }
  },
  { immediate: true },
);

onBeforeUnmount(() => store.stopRunStream());
</script>

<template>
  <main class="agent-page">
    <div class="page-shell">
      <header class="workspace-topbar">
        <div class="brand-lockup"><div class="brand-mark"><AgentIcon name="spark" :size="19" /></div><div><strong>Career<span>OS</span></strong><small>个人职业工作台</small></div></div>
        <div class="topbar-center"><span class="topbar-dot" /> AI 工作台 <span class="topbar-divider">/</span> <span class="muted">晓屿的成长空间</span></div>
        <div class="topbar-actions"><button class="quiet-button">⌘ K <span>快速操作</span></button><button class="avatar-button">LY</button></div>
      </header>

      <div class="mobile-switch"><button :class="{ active: mobilePanel === 'overview' }" @click="mobilePanel = 'overview'">工作台</button><button :class="{ active: mobilePanel === 'coach' }" @click="mobilePanel = 'coach'">AI 助手</button></div>

      <div class="workspace-grid">
        <aside class="conversation-column" :class="{ 'mobile-hidden': mobilePanel !== 'coach' }"><AgentConversation /></aside>
        <section class="dashboard-column" :class="{ 'mobile-hidden': mobilePanel !== 'overview' }">
          <div v-if="!store.featureAvailable" class="demo-banner unavailable">职业规划 Agent 当前仅对灰度用户开放。</div>
          <div v-else-if="store.isDashboardMock" class="demo-banner">对话和分析进度来自真实 Agent；画像、匹配度、路线图、岗位与行动卡片仍为界面演示数据。</div>
          <div class="welcome-row"><div><p class="section-kicker">TUESDAY · 07 JUN 2025</p><h1>早上好，晓屿 <span>✦</span></h1><p class="welcome-subtitle">这是你本周的职业成长快照，保持节奏，持续靠近目标。</p></div><button class="run-button" :disabled="!store.featureAvailable || store.runState === 'running' || store.isSending" @click="runAnalysis"><AgentIcon name="spark" :size="16" /> {{ store.runState === 'running' || store.isSending ? '分析中...' : '发起新一轮对话分析' }}</button></div>

          <section class="profile-strip card-surface"><div class="profile-main"><div class="large-avatar">LY<div class="online-mark" /></div><div><div class="profile-name">{{ agentProfile.name }} <span class="profile-badge">{{ agentProfile.status }}</span></div><p>{{ agentProfile.school }} · {{ agentProfile.major }} · {{ agentProfile.grade }}</p><div class="profile-tags"><span v-for="tag in agentProfile.tags" :key="tag">{{ tag }}</span></div></div></div><div class="profile-stats"><div><strong>{{ agentProfile.completion }}<small>%</small></strong><span>画像完整度</span></div><div><strong>92<small>%</small></strong><span>目标匹配度</span></div><div><strong>+12<small>h</small></strong><span>本周投入</span></div></div><button class="edit-profile">编辑画像 <AgentIcon name="arrow" :size="13" /></button></section>

          <section class="insight-banner"><div class="banner-orb"><AgentIcon name="spark" :size="22" /></div><div><p>AI 洞察</p><strong>你的“技术理解 + 用户洞察”是稀缺组合，建议优先探索 AI 产品方向。</strong></div><span class="banner-confidence">HIGH CONFIDENCE</span></section>

          <div class="section-heading"><div><p class="section-kicker">DIRECTION MAP</p><h2>职业方向罗盘</h2></div><span class="heading-note">基于 6 项能力 · 更新于刚刚</span></div>
          <section class="direction-grid"><article v-for="direction in careerDirections" :key="direction.id" class="direction-card" :class="[{ selected: selectedDirection.id === direction.id }, direction.tone]" @click="chooseDirection(direction.id)"><div class="direction-top"><span class="direction-rank">{{ direction.rank }}</span><span class="match-number">{{ direction.match }}<small>% 匹配</small></span></div><h3>{{ direction.title }}</h3><p>{{ direction.summary }}</p><div class="match-bar"><i :style="{ width: `${direction.match}%` }" /></div><div class="evidence"><span v-for="item in direction.evidence" :key="item"><AgentIcon name="check" :size="12" />{{ item }}</span></div><div v-if="selectedDirection.id === direction.id" class="selected-corner"><AgentIcon name="check" :size="13" /></div></article></section>

          <section class="market-row"><div class="section-heading compact"><div><p class="section-kicker">MARKET PULSE</p><h2>行业正在发生什么</h2></div><span class="live-label" :class="{ mock: store.isDashboardMock }"><i /> {{ store.isDashboardMock ? '演示数据' : '实时数据' }}</span></div><div class="signal-grid"><div v-for="signal in marketSignals" :key="signal.label" class="signal"><strong>{{ signal.value }}</strong><span>{{ signal.label }}</span></div></div></section>

          <div class="split-heading"><div class="section-heading compact"><div><p class="section-kicker">SKILL PROFILE</p><h2>能力雷达</h2></div></div><div class="section-heading compact"><div><p class="section-kicker">NEXT 4 YEARS</p><h2>成长路线图</h2></div><span class="heading-note">目标：{{ selectedDirection.title }}</span></div></div>
          <div class="skill-roadmap-grid"><section class="card-surface skill-card"><div class="skill-card-top"><div><strong>当前能力画像</strong><p>与目标岗位要求的对比</p></div><span class="score-pill">68 <small>平均分</small></span></div><div class="radar-wrap"><AgentRadarChart :skills="skills" /><div class="radar-legend"><span><i class="current-dot" />当前能力</span><span><i class="target-dot" />岗位期望</span></div></div><div class="skill-list"><div v-for="skill in skills" :key="skill.name" class="skill-row"><span>{{ skill.name }}</span><div class="skill-progress"><i :style="{ width: `${skill.score}%`, background: skill.color }" /></div><b>{{ skill.score }}</b><small>目标 {{ skill.target }}</small></div></div><div class="gap-note"><AgentIcon name="spark" :size="14" /><span>优先补强：<strong>{{ highestGap.name }}</strong> · 这是进入目标岗位的最短路径</span></div></section><section class="roadmap-card"><div v-for="(item, index) in roadmap" :key="item.year" class="roadmap-item" :class="{ current: index === 0 }"><div class="roadmap-marker"><i /> <span v-if="index < roadmap.length - 1" /></div><div class="roadmap-copy"><div class="roadmap-title"><strong>{{ item.year }}</strong><span>{{ item.period }}</span></div><h3>{{ item.focus }}</h3><div class="roadmap-items"><span v-for="point in item.items" :key="point"><AgentIcon name="check" :size="11" />{{ point }}</span></div></div></div></section></div>

          <div class="section-heading opportunities-heading"><div><p class="section-kicker">CURATED FOR YOU</p><h2>值得关注的机会</h2></div><button class="text-button">查看全部 <AgentIcon name="arrow" :size="13" /></button></div>
          <section class="opportunity-list"><article v-for="opportunity in opportunities" :key="opportunity.id" class="opportunity-card"><div class="company-logo" :class="`logo-${opportunity.id}`">{{ opportunity.logo }}</div><div class="opportunity-copy"><div class="opportunity-title"><h3>{{ opportunity.title }}</h3><span>匹配 {{ opportunity.match }}%</span></div><p>{{ opportunity.company }} · {{ opportunity.location }}</p><div class="opportunity-tags"><span v-for="tag in opportunity.tags" :key="tag">{{ tag }}</span></div></div><div class="opportunity-end"><strong>{{ opportunity.salary }}</strong><button class="save-button" :class="{ saved: store.savedOpportunities.includes(opportunity.id) }" @click="toggleSaved(opportunity.id)"><AgentIcon name="bookmark" :size="16" />{{ store.savedOpportunities.includes(opportunity.id) ? '已收藏' : '收藏' }}</button></div></article></section>

          <div class="lower-grid"><section><div class="section-heading compact"><div><p class="section-kicker">CAREER PATH</p><h2>一条可行的成长路径</h2></div></div><div class="path-card card-surface"><div v-for="item in careerPath" :key="item.level" class="path-step" :class="{ active: item.active }"><div class="path-node">{{ item.active ? '●' : '○' }}</div><div><small>{{ item.level }}</small><strong>{{ item.role }}</strong><span>{{ item.years }} · {{ item.salary }}</span></div></div></div></section><section><div class="section-heading compact"><div><p class="section-kicker">YOUR INPUT · DEMO</p><h2>简历解析界面演示</h2></div></div><div class="upload-card card-surface"><div v-if="!store.uploadedDocument" class="upload-empty" @click="openFilePicker"><div class="upload-icon"><AgentIcon name="upload" :size="18" /></div><div><strong>选择本地文件体验交互</strong><p>当前不会上传或真实解析文件，结果仅为演示</p></div><button>选择文件</button></div><div v-else class="uploaded-file"><div class="file-icon"><AgentIcon name="file" :size="19" /></div><div><strong>{{ store.uploadedDocument.name }}</strong><p>{{ store.uploadedDocument.meta }} · 演示识别 {{ store.uploadedDocument.parsed.length }} 个模块</p></div><button @click="store.removeDocument">移除</button></div><div v-if="store.isUploading" class="upload-progress"><i /></div><input ref="fileInput" type="file" accept=".pdf,.doc,.docx" hidden @change="handleFile" /><button v-if="!store.uploadedDocument" class="use-mock" @click="store.useMockDocument">使用示例简历体验</button></div></section></div>

